const ctx = $('Build AI Context').first().json;
const raw = $input.first().json || {};
const aiFailed = raw.ai_failed === true;

// Extract raw text from the AI Agent node output
let outputText = '';
if (typeof raw === 'string') {
  outputText = raw;
} else if (raw.output !== undefined) {
  outputText = typeof raw.output === 'string' ? raw.output : JSON.stringify(raw.output);
} else if (raw.text !== undefined) {
  outputText = typeof raw.text === 'string' ? raw.text : JSON.stringify(raw.text);
} else if (raw.message !== undefined) {
  outputText = typeof raw.message === 'string' ? raw.message : JSON.stringify(raw.message);
} else {
  outputText = JSON.stringify(raw);
}

// Extract JSON if present in outputText
let ai = {};
try {
  const jsonMatch = outputText.match(/\\{[\\s\\S]*\\}/);
  if (jsonMatch) {
    ai = JSON.parse(jsonMatch[0]);
  }
} catch (e) {
  ai = {};
}
if (!ai || typeof ai !== 'object') ai = {};

const str = v => (v === null || v === undefined) ? '' : String(v).trim();
const now = new Date().toISOString();

const msgText = String(ctx.message_text || '');
const hasDeva = /[\\u0900-\\u097F]/.test(msgText);
let lang = str(ai.language).toLowerCase();
if (lang === 'hindi' && !hasDeva) lang = 'hinglish';
lang = lang || (hasDeva ? 'hindi' : (/(\\bhai\\b|\\bhain\\b|\\bkya\\b|\\bnahi\\b|\\bchahiye\\b|\\bkab\\b|\\bkitna\\b|\\baap\\b)/i.test(msgText) ? 'hinglish' : 'english'));

const fallbackByLang = {
  hindi: 'नमस्ते! एमोलिक ग्रुप में आपका स्वागत है। फरीदाबाद में फ्लैट (1, 2, 3 BHK) या प्लॉट की जानकारी के लिए बताइए आप क्या देख रहे हैं?',
  hinglish: 'Namaste! Amolik Group mein aapka swagat hai. Main aapki kya madad kar sakta hoon? Aap Faridabad mein flat dekh rahe hain ya residential plot?',
  english: 'Hello! Welcome to Amolik Group. How can I assist you today? Are you looking for flats or residential plots in Faridabad?',
};
const defaultHandoff = fallbackByLang[lang] || fallbackByLang.hinglish;

// Determine 1 or 2 messages
let reply1 = str(ai.reply_1);
let reply2 = str(ai.reply_2);
let reply = str(ai.reply);

if (reply1) {
  if (!reply) reply = [reply1, reply2].filter(Boolean).join('\\n\\n');
} else if (reply) {
  if (reply.includes('\\n\\n')) {
    const parts = reply.split(/\\n\\n+/).map(p => p.trim()).filter(Boolean);
    reply1 = parts[0] || reply;
    reply2 = parts.slice(1).join('\\n\\n');
  } else {
    const match = reply.match(/^([\\s\\S]+?[.!?])\\s+((?:[A-Z\\u0900-\\u097F]|kya|aap|aur|kaisa|kaunsa|ye|in|is)[\\s\\S]+?\\?)$/i);
    if (match && match[1].length > 30) {
      reply1 = match[1].trim();
      reply2 = match[2].trim();
    } else {
      reply1 = reply;
      reply2 = '';
    }
  }
} else {
  if (aiFailed) {
    if (/^(hi|hello|hii|hey|namaste|ha|haan)$/i.test(msgText.trim())) {
      reply1 = defaultHandoff;
    } else if (/(kaise|kaisa|how are you)/i.test(msgText.trim())) {
      reply1 = 'Main bilkul badhiya hoon, aapka shukriya! Aap bataiye aap kaise hain?';
      reply2 = 'Amolik Group mein aapki kya madad kar sakta hoon?';
    } else {
      reply1 = str(ctx.handoff_message) || defaultHandoff;
    }
  } else {
    reply1 = defaultHandoff;
  }
  reply = [reply1, reply2].filter(Boolean).join('\\n\\n');
}

// Check if customer asked for visit or meeting
const customerAskedVisit = /(visit|dekhne|aana hai|location dekh|aau|aaye|milna|meeting|appointment|fix karo|fix kro|site dekh)/i.test(msgText);
if (!customerAskedVisit) {
  // Strip unprompted site visit pitches if customer did NOT ask
  reply1 = reply1.replace(/\\s*(?:Kya\\s+aap\\s+)?(?:is|in)?\\s*(?:property|project[s]?)?\\s*(?:ke\\s+baare\\s+mein\\s+aur\\s+jaankari\\s+chahiye\\s+ya\\s+)?(?:ke\\s+liye\\s+)?site\\s+visit\\s+schedule\\s+karna\\s+chahenge\\??/gi, '').trim();
  reply2 = reply2.replace(/\\s*(?:Kya\\s+aap\\s+)?(?:is|in)?\\s*(?:property|project[s]?)?\\s*(?:ke\\s+baare\\s+mein\\s+aur\\s+jaankari\\s+chahiye\\s+ya\\s+)?(?:ke\\s+liye\\s+)?site\\s+visit\\s+schedule\\s+karna\\s+chahenge\\??/gi, '').trim();
}

// Strip repetitive smiling emojis from end of replies
reply1 = reply1.replace(/[\\u{1F600}-\\u{1F64F}\\u{1F300}-\\u{1F5FF}\\u{1F680}-\\u{1F6FF}\\u{1F900}-\\u{1F9FF}\\u{2600}-\\u{26FF}\\u{2700}-\\u{27BF}]+\\s*$/u, '').trim();
reply2 = reply2.replace(/[\\u{1F600}-\\u{1F64F}\\u{1F300}-\\u{1F5FF}\\u{1F680}-\\u{1F6FF}\\u{1F900}-\\u{1F9FF}\\u{2600}-\\u{26FF}\\u{2700}-\\u{27BF}]+\\s*$/u, '').trim();

reply1 = reply1.slice(0, 3000);
reply2 = reply2.slice(0, 3000);
const hasSecondMessage = Boolean(reply2 && reply2.length > 0 && reply2 !== reply1);
reply = [reply1, reply2].filter(Boolean).join('\\n\\n');

// Human handoff detection
const humanRegex = /(\\bhuman\\b|\\bagent\\b|representative|real person|\\bmanager\\b|\\bowner\\b|\\binsaan\\b|\\binsan\\b|staff se baat|kisi se baat|call me|call karo|phone karo|baat karni hai|baat krwao|baat karwao|baat karado|call karwao|connect karo|इंसान|मैनेजर)/i;
const customerAskedHuman = humanRegex.test(msgText);
const handoff = ai.handoff_required === true || customerAskedHuman;
const handoffReason = customerAskedHuman && !ai.handoff_required 
  ? 'Customer requested a call / human representative / owner discussion' 
  : str(ai.handoff_reason) || (handoff ? 'Customer requested human assistance' : '');

const keepHumanTakeover = ctx.human_takeover === true;

// Lead updates
const ex = ctx.existing_lead || {};
const pick = (n, o) => str(n) ? str(n) : (str(o) || null);

const lead = {
  business_id: ctx.business_id,
  customer_phone: ctx.customer_phone,
  customer_name: pick(ai.customer_name, ex.customer_name || ctx.customer_name),
  interested_service: pick(ai.interested_service, ex.interested_service),
  requirements: pick(ai.requirements, ex.requirements),
  budget: pick(ai.budget, ex.budget),
  location: pick(ai.preferred_location, ex.location),
  preferred_appointment_time: pick(ai.preferred_appointment_time, ex.preferred_appointment_time),
  last_intent: str(ai.intent) || null,
  last_message_at: now,
  updated_at: now,
};

let status = 'new';
if (lead.interested_service || lead.budget || lead.location) status = 'interested';
if (lead.customer_name && lead.interested_service && (lead.requirements || lead.budget || lead.preferred_appointment_time)) status = 'qualified';
if (handoff) status = 'follow_up_required';
lead.status = status;

// Appointment / Visit request detection
const apptRequested = Boolean(
  (!aiFailed && (ai.appointment_requested === true || String(ai.appointment_requested) === 'true')) ||
  customerAskedVisit
);

// Owner Notification Message
const ownerPhone = String(ctx.owner_phone || '917250307422').replace(/\\D/g, '');
const custName = lead.customer_name || ctx.customer_name || 'Customer';
const custPhone = ctx.customer_phone;

let ownerAlertText = '';
if (apptRequested) {
  ownerAlertText = \`🔔 *New Meeting / Site Visit Request!*\\n👤 *Customer:* \${custName}\\n📱 *Phone:* +\${custPhone}\\n🏠 *Property / Requirement:* \${lead.interested_service || lead.requirements || 'Meeting / Site Visit'}\\n📍 *Location:* \${lead.location || 'Faridabad'}\\n💰 *Budget:* \${lead.budget || 'Not specified'}\\n⏰ *Preferred Time:* \${lead.preferred_appointment_time || 'Customer requested meeting'}\\n💬 *Customer wrote:* "\${ctx.message_text.slice(0, 200)}"\\n👉 *Action:* Please call the customer to confirm the meeting slot!\

const orig = $('Validate Message').first().json;
const rows = $input.all().map(i => i.json).filter(r => r && r.body && r.direction === 'inbound');

if (!rows.length) {
  return [{ json: { should_process: true, ...orig, combined_text: orig.message_text, batch_count: 1, batch_message_ids: [orig.message_id] } }];
}

// Sort oldest first
const sorted = rows.sort((a, b) => new Date(a.created_at || a.message_timestamp) - new Date(b.created_at || b.message_timestamp));

// The newest message in this batch
const newest = sorted[sorted.length - 1];
const newestId = String(newest.message_id || newest.wa_message_id || '');
const currentId = String(orig.message_id || '');

// Only yield if there is definitely a newer message in this burst
if (currentId && newestId && currentId !== newestId) {
  return [{ json: { should_process: false, reason: 'superseded_by_newer_message', current_id: currentId, newest_id: newestId } }];
}

// Combine all messages from recent burst (received within last 45 seconds)
const cutoff = Date.now() - 45000;
const recentBurst = sorted.filter(m => {
  const t = new Date(m.created_at || m.message_timestamp).getTime();
  return !isNaN(t) && t >= cutoff;
});
const batch = recentBurst.length ? recentBurst : [newest];

const combinedText = batch.map(m => String(m.body).trim()).filter(Boolean).join('\n').slice(0, 3000);

// Extract latest quoted_message_id if any message in batch had one
let quotedMsgId = orig.quoted_message_id || null;
for (let i = batch.length - 1; i >= 0; i--) {
  const m = batch[i];
  let meta = m.metadata;
  if (typeof meta === 'string') { try { meta = JSON.parse(meta); } catch(e) { meta = {}; } }
  if (m.quoted_message_id) { quotedMsgId = m.quoted_message_id; break; }
  if (meta && meta.quoted_message_id) { quotedMsgId = meta.quoted_message_id; break; }
}

return [{ json: {
  should_process: true,
  phone_number_id: orig.phone_number_id,
  display_phone_number: orig.display_phone_number,
  customer_phone: orig.customer_phone,
  customer_name: orig.customer_name,
  session_id: orig.session_id,
  message_id: newestId || currentId,
  message_text: combinedText || orig.message_text,
  original_single_text: orig.message_text,
  batch_count: batch.length,
  batch_message_ids: batch.map(b => b.message_id || b.wa_message_id),
  quoted_message_id: quotedMsgId,
  message_timestamp: newest.message_timestamp || orig.message_timestamp,
} }];

const prev = $('Aggregate & Check Winner').first().json;
const rows = $input.all().map(i => i.json).filter(r => r && r.body);
let quotedText = '';
let quotedMetadata = {};
if (rows.length) {
  quotedText = rows[0].body || '';
  quotedMetadata = typeof rows[0].metadata === 'string' ? JSON.parse(rows[0].metadata || '{}') : (rows[0].metadata || {});
}
return [{ json: {
  ...prev,
  quoted_found: !!quotedText,
  quoted_body: quotedText,
  quoted_metadata: quotedMetadata,
} }];

const prev = $('Aggregate & Check Winner').first().json;
return [{ json: {
  ...prev,
  quoted_found: false,
  quoted_body: '',
  quoted_metadata: {},
} }];

// Accepts only fresh, inbound customer TEXT messages. Drops status events,
// echoes of our own number, non-text media, and messages outside the reply window.
const cfg = $('Workflow Config').first().json;
const windowHours = Number(cfg.reply_window_hours || 24);
const out = [];
for (const item of $('WhatsApp Trigger').all()) {
  const j = item.json || {};
  const values = [];
  if (Array.isArray(j.entry)) {
    for (const e of j.entry) for (const c of (e.changes || [])) values.push(c.value || {});
  } else if (j.value) {
    values.push(j.value);
  } else {
    values.push(j);
  }
  for (const v of values) {
    const meta = v.metadata || {};
    const msgs = Array.isArray(v.messages) ? v.messages : [];
    for (const m of msgs) {
      if (!m || m.type !== 'text' || !m.text || !m.text.body) continue;
      const from = String(m.from || '').replace(/\D/g, '');
      const own = String(meta.display_phone_number || '').replace(/\D/g, '');
      if (!from || !meta.phone_number_id || from === own) continue;
      const tsMs = Number(m.timestamp || 0) * 1000;
      if (tsMs && (Date.now() - tsMs) / 3600000 > windowHours) continue;
      const contacts = Array.isArray(v.contacts) ? v.contacts : [];
      const contact = contacts.find(c => String(c.wa_id) === from) || contacts[0] || {};
      const text = String(m.text.body).trim().slice(0, 3000);
      if (!text) continue;
      const context = m.context || {};
      const quotedId = String(context.id || '');
      out.push({ json: {
        phone_number_id: String(meta.phone_number_id),
        display_phone_number: own,
        customer_phone: from,
        customer_name: (contact.profile && contact.profile.name) || '',
        message_id: String(m.id || ''),
        quoted_message_id: quotedId || null,
        message_text: text,
        message_timestamp: tsMs ? new Date(tsMs).toISOString() : new Date().toISOString(),
        session_id: String(meta.phone_number_id) + ':' + from,
        received_epoch: Date.now(),
      } });
    }
  }
}
return out.filter(o => o.json.message_id).slice(0, 1);

const cfg = $('Workflow Config').first().json;
// Get the customer message data with combined text & quoted context:
let msg = null;
try { msg = $('Pass Direct Message').first()?.json; } catch (e) {}
if (!msg || !msg.customer_phone) {
  try { msg = $('Resolve Quoted Data').first()?.json; } catch (e) {}
}
if (!msg || !msg.customer_phone) {
  try { msg = $('Aggregate & Check Winner').first()?.json; } catch (e) {}
}
if (!msg || !msg.customer_phone) {
  msg = $('Validate Message').first().json;
}

// Business rows retrieved from Supabase
const bizRows = $('Identify Business').all().map(i => i.json).filter(r => r && r.id);
let business = null;
let source = 'none';

if (bizRows.length) {
  business = bizRows[0];
  source = 'supabase';
} else if (cfg.test_mode === true && (!cfg.test_phone_number_id || String(cfg.test_phone_number_id) === String(msg.phone_number_id))) {
  business = {
    id: cfg.test_business_id || 'biz_test',
    name: cfg.test_business_name,
    phone_number_id: msg.phone_number_id,
    services: cfg.test_services,
    products: '',
    prices: '',
    faqs: cfg.test_faqs,
    opening_hours: cfg.test_opening_hours,
    ai_tone: cfg.test_ai_tone,
    contact_details: cfg.test_contact_details,
    booking_system: null,
    handoff_message: '',
  };
  source = 'test_config';
}

return [{ json: {
  ...msg,
  business_found: !!business,
  business_source: source,
  business: business || {},
} }];

const cfg = $('Workflow Config').first().json;
const msg = $('Resolve Business').first().json;
const biz = msg.business || {};
let settings = biz.settings;
if (typeof settings === 'string') { try { settings = JSON.parse(settings); } catch (e) { settings = {}; } }
if (!settings || typeof settings !== 'object') settings = {};
const clean = items => items.map(i => i.json).filter(r => r && typeof r === 'object' && Object.keys(r).length > 0 && !r.error);
const lead = clean($('Fetch Existing Lead').all())[0] || null;
const conv = clean($('Check Human Takeover').all())[0] || null;

// History: token-optimized, last 4 turns only, oldest first
const hist = clean($('Retrieve Chat History').all())
  .filter(r => r.body && r.wa_message_id !== msg.message_id && r.message_id !== msg.message_id)
  .filter(r => String(r.session_id) === String(msg.session_id))
  .filter(r => r.status !== 'failed')
  .sort((a, b) => new Date(a.created_at) - new Date(b.created_at));

const lastAt = hist.length ? new Date(hist[hist.length - 1].created_at).getTime() : 0;
const hoursSinceLast = lastAt ? (Date.now() - lastAt) / 3600000 : null;
const isNewConversation = !hist.length || hoursSinceLast > 12;
const outbound = hist.filter(r => r.direction === 'outbound');
// Max 4 recent messages, compact snippet to save tokens
const historyText = hist.slice(-4).map(r => (r.direction === 'inbound' ? 'Customer: ' : 'Assistant: ') + String(r.body).slice(0, 250)).join('\n');

// Human handoff: only if explicitly active in database
const handoffActive = !!(conv && (conv.human_takeover === true || conv.human_takeover === 'true'));

// Business info: compact and token-efficient
const has = v => v !== undefined && v !== null && v !== '' && !(Array.isArray(v) && !v.length) && !(typeof v === 'object' && !Array.isArray(v) && !Object.keys(v).length);
const pick = (...keys) => { for (const k of keys) { if (has(biz[k])) return biz[k]; if (has(settings[k])) return settings[k]; } return null; };
const fmt = v => !has(v) ? 'Not provided' : (typeof v === 'string' ? v : JSON.stringify(v));

const businessContext = [
  'Business Name: ' + fmt(biz.name),
  'Properties & Projects: ' + fmt(pick('services')),
  'Prices & Configurations: ' + fmt(pick('prices', 'pricing')),
  'Frequently Asked Questions (FAQs): ' + fmt(pick('faqs')),
  'Opening Hours: ' + fmt(pick('opening_hours', 'hours')),
  'Location & Address: ' + fmt(pick('location', 'address')),
  'Contact Details: ' + fmt(pick('contact_details', 'contact')),
].filter(Boolean).join('\n\n');

// Quoted context
let quotedContext = '';
if (msg.quoted_found && msg.quoted_body) {
  quotedContext = 'QUOTED MESSAGE CONTEXT:\nCustomer replied to: "' + msg.quoted_body.slice(0, 300) + '"\n(Answer specifically about this property/detail!)\n';
}

// Short message guidance
const textTrim = String(msg.message_text || '').trim();
const isShort = textTrim.length <= 4 || /^(yes|haan|ha|theek hai|ok|okay|\.|\?|details|send|price)$/i.test(textTrim);
let shortMsgGuidance = '';
if (isShort) {
  shortMsgGuidance = 'SHORT MESSAGE NOTE: Customer sent "' + textTrim + '". Interpret in context of previous question or ask 1 brief clarification.';
}

// Structured lead memory
const leadKnown = lead ? [
  'Customer Name: ' + fmt(lead.customer_name || msg.customer_name),
  'Interested Property: ' + fmt(lead.interested_service),
  'Location: ' + fmt(lead.location),
  'Budget: ' + fmt(lead.budget),
  'Requirements: ' + fmt(lead.requirements),
  'Visit/Call Time: ' + fmt(lead.preferred_appointment_time),
].join('\n') : 'No saved lead details yet.';

const ownerPhone = pick('owner_phone') || cfg.owner_phone || '917250307422';
const ownerName = pick('owner_name') || 'Sanskar Sharma';
const clientSystemPrompt = biz.system_prompt || pick('system_prompt') || '';
const clientTone = pick('ai_tone', 'tone') || 'Warm, natural, conversational, polite, helpful, and human-like Indian sales assistant. Speaks fluent conversational Hinglish/Hindi or English.';

return [{ json: {
  ...msg,
  business_id: String(biz.id || ''),
  business_name: biz.name || '',
  owner_phone: String(ownerPhone).replace(/\D/g, ''),
  owner_name: ownerName,
  client_system_prompt: clientSystemPrompt,
  ai_tone: clientTone,
  handoff_message: pick('handoff_message') || '',
  business_context: businessContext,
  quoted_context: quotedContext,
  short_message_guidance: shortMsgGuidance,
  lead_known: leadKnown,
  existing_lead: lead || {},
  history_text: historyText,
  history_count: hist.length,
  assistant_turns: outbound.length,
  is_new_conversation: isNewConversation,
  human_takeover: handoffActive,
} }];

